(function() {
  window.CardSpoke.Plugin.register('auto-save-indicator', {
    manifest: {
      name: 'Auto-Save Indicator',
      version: '1.0.0',
      author: 'CardSpoke Community',
      description: 'Displays a live save status badge that tracks card save operations',
      layer: 'feature',
      permissions: []
    },
    setup: async function(ctx) {
      var self = this;
      var badge = document.createElement('div');
      badge.className = 'save-indicator idle';
      badge.id = 'save-indicator';
      badge.textContent = 'Ready';
      document.body.appendChild(badge);
      self._badge = badge;
      var saveCount = 0;
      var errorCount = 0;
      var lastSaveTime = null;
      var resetTimer = null;
      function setState(state, text) {
        badge.className = 'save-indicator ' + state;
        badge.textContent = text;
      }
      function scheduleIdle() {
        if (resetTimer) clearTimeout(resetTimer);
        resetTimer = setTimeout(function() {
          var elapsed = lastSaveTime ? Math.round((Date.now() - lastSaveTime) / 1000) : 0;
          var msg = saveCount > 0 ? saveCount + ' saves' : 'Ready';
          if (elapsed > 0 && elapsed < 300) {
            msg += ' (' + elapsed + 's ago)';
          }
          setState('idle', msg);
        }, 3000);
      }
      if (window.CardSpoke && window.CardSpoke.Middleware) {
        window.CardSpoke.Middleware.register({
          name: 'save-indicator-before',
          priority: 100,
          operations: ['card.save'],
          handler: async function(mwCtx, next) {
            setState('saving', 'Saving...');
            try {
              await next();
              saveCount++;
              lastSaveTime = Date.now();
              var time = new Date().toLocaleTimeString();
              setState('saved', 'Saved at ' + time);
              scheduleIdle();
            } catch (err) {
              errorCount++;
              setState('error', 'Save failed (' + errorCount + ' errors)');
              scheduleIdle();
              throw err;
            }
          }
        });
      }
      self._resetTimer = resetTimer;
      ctx.logger.info('Auto-Save Indicator loaded');
    },
    teardown: async function(ctx) {
      if (window.CardSpoke && window.CardSpoke.Middleware) {
        window.CardSpoke.Middleware.unregister('save-indicator-before');
      }
      if (this._resetTimer) clearTimeout(this._resetTimer);
      if (this._badge && this._badge.parentNode) {
        this._badge.remove();
      }
      ctx.logger.info('Auto-Save Indicator disabled');
    }
  });
})();
